import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive")
    system = platform.system()
    if system == "Windows":
        command = ['wmic', 'cpu', 'get', 'loadpercentage']
    else:
        command = ['top', '-bn1']
    records = []
    end_time = time.time() + duration
    while time.time() < end_time:
        if system == "Windows":
            output = subprocess.check_output(command).decode()
            lines = output.strip().split('\n')
            if len(lines) > 1:
                usage = lines[1].strip()
            else:
                usage = "0"
        else:
            output = subprocess.check_output(command).decode()
            lines = output.split('\n')
            for line in lines:
                if '%Cpu(s)' in line:
                    parts = line.split(',')
                    idle = float(parts[3].split()[0].replace('%id', ''))
                    usage = str(100.0 - idle)
                    break
            else:
                usage = "0"
        records.append({'timestamp': time.time(), 'cpu_usage': usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
        return LOGFILE_PATH
    except IOError:
        return None

