def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    try:
        process = subprocess.Popen(['Rscript', r_script_path])
        start_time = time.time()
        while time.time() - start_time < duration:
            if os.path.exists(output_path):
                process.terminate()
                return True, 'File generated successfully within the specified duration.'
            time.sleep(0.1)
        process.terminate()
        return False, 'File not generated within the specified duration.'
    except Exception:
        if 'process' in locals():
            process.terminate()
        return False, 'File not generated within the specified duration.'

import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range)
    results = {}
    for ip in network:
        try:
            if subprocess.os.name == 'nt':
                response = subprocess.run(['ping', '-n', '1', str(ip)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            else:
                response = subprocess.run(['ping', '-c', '1', str(ip)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            results[str(ip)] = response.returncode == 0
        except subprocess.CalledProcessError as e:
            raise e
    return results

