import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    failed_files = []
    if not os.path.exists(src_folder):
        return {'success': False, 'message': 'Source folder does not exist', 'failed_files': []}
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)
    files = glob(os.path.join(src_folder, '*'))
    for file_path in files:
        if os.path.isfile(file_path):
            try:
                subprocess.run(['gzip', file_path], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                compressed_file = file_path + '.gz'
                shutil.move(compressed_file, dst_folder)
            except Exception:
                failed_files.append(os.path.basename(file_path))
    success = len(failed_files) == 0
    message = 'All files compressed and moved successfully' if success else 'Some files failed to compress or move'
    return {'success': success, 'message': message, 'failed_files': failed_files}

import subprocess
import logging
def task_func(filepath):
    logging.basicConfig(level=logging.INFO)
    try:
        result = subprocess.run(['g++', filepath], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        if result.returncode == 0:
            logging.info('Compilation successful')
        else:
            raise subprocess.CalledProcessError(result.returncode, ['g++', filepath], output=result.stdout, stderr=result.stderr)
    except FileNotFoundError as e:
        logging.error(f'Compiler not found or file does not exist: {e}')
        raise

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script path {script_path} does not exist")
    proc = subprocess.Popen(['bash', script_path])
    start_time = time.time()
    total_cpu = 0.0
    max_memory = 0
    while True:
        try:
            p = psutil.Process(proc.pid)
            cpu_times = p.cpu_times()
            total_cpu = cpu_times.user + cpu_times.system
            mem_info = p.memory_info()
            if mem_info.rss > max_memory:
                max_memory = mem_info.rss
        except psutil.NoSuchProcess:
            break
        if proc.poll() is not None:
            break
        if time.time() - start_time > timeout:
            proc.terminate()
            break
        time.sleep(0.1)
    return {'CPU Usage': total_cpu, 'Memory Usage': max_memory}
